BEGIN;
CREATE TEMP TABLE retry_checks(name text,passed boolean NOT NULL);
DO $$
DECLARE s uuid; p uuid; o uuid; l uuid; a jsonb; b jsonb; input jsonb; marker text:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)); key text:=encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'); req text:=repeat('b',64); bad boolean:=false; owner_a uuid:=gen_random_uuid(); owner_b uuid:=gen_random_uuid();
BEGIN
 INSERT INTO public.sellers(user_id,store_username,store_name) VALUES('retry-'||marker,'retry_'||lower(marker),'Disposable retry fixture') RETURNING id INTO s;
 INSERT INTO public.products(seller_id,title,price,currency,stock,is_active,delivery_options,catalog_visible) VALUES(s,'Fixture',100,'MXN',1,true,ARRAY['meetup'],true) RETURNING id INTO p;
 INSERT INTO public.purchase_links(seller_id,product_id,public_id,status) VALUES(s,p,marker,'active') RETURNING id INTO l;
 input:=jsonb_build_object('publicId',marker,'buyerName','TEST','buyerEmail','fixture@example.invalid','buyerPhone','555','address','{}'::jsonb,'deliveryMethod','meetup');
 a:=public.reserve_checkout_attempt(key,req,'quick','RF-RETRY-'||marker,repeat('a',64),input);o:=(a->>'id')::uuid;
 b:=public.reserve_checkout_attempt(key,req,'quick','RF-IGNORED-'||marker,repeat('a',64),input);
 INSERT INTO retry_checks VALUES('lost response reuses order even with last unit reserved',a->>'id'=b->>'id' AND (SELECT stock=0 FROM public.products WHERE id=p) AND (SELECT count(*)=1 FROM public.orders WHERE seller_id=s));
 INSERT INTO retry_checks VALUES('retry preserves line snapshot',(SELECT count(*)=1 FROM public.order_items WHERE order_id=o) AND b->'order_items'->0->>'title'='Fixture');
 BEGIN PERFORM public.reserve_checkout_attempt(key,repeat('c',64),'quick','RF-BAD',repeat('a',64),input); EXCEPTION WHEN OTHERS THEN bad:=true; END;
 INSERT INTO retry_checks VALUES('changed payload cannot reuse credential',bad);
 a:=public.bind_checkout_stripe_request(key,req,jsonb_build_object('client_reference_id',o,'expires_at',123));
 b:=public.bind_checkout_stripe_request(key,req,jsonb_build_object('client_reference_id',o,'expires_at',456));
 INSERT INTO retry_checks VALUES('Stripe parameters are immutable across retries',a=b AND (b->>'expires_at')::int=123);
 UPDATE public.products SET stock=1 WHERE id=p;
 key:=encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex');
 input:=input||jsonb_build_object('username','retry_'||lower(marker),'items',jsonb_build_array(jsonb_build_object('productId',p,'quantity',1)));
 a:=public.reserve_checkout_attempt(key,req,'catalog','RF-CART-'||marker,repeat('a',64),input);
 b:=public.reserve_checkout_attempt(key,req,'catalog','RF-CART-IGNORE-'||marker,repeat('a',64),input);
 INSERT INTO retry_checks VALUES('catalog retries reserve once',a->>'id'=b->>'id' AND (SELECT stock=0 FROM public.products WHERE id=p) AND (SELECT count(*)=2 FROM public.orders WHERE seller_id=s));
 UPDATE public.orders SET status='SHIPPED',payment_status='SUCCEEDED' WHERE id=o;
 INSERT INTO public.shipments(order_id,provider,tracking_number,service_code,carrier_name) VALUES(o,'FEDEX','TEST-'||marker,'TEST','FedEx');
 SELECT value INTO a FROM public.claim_tracking_refresh(owner_a,20) value WHERE value->>'order_id'=o::text;
 SELECT value INTO b FROM public.claim_tracking_refresh(owner_b,20) value WHERE value->>'order_id'=o::text;
 INSERT INTO retry_checks VALUES('one tracking worker owns a due shipment',a->>'tracking_poll_owner'=owner_a::text AND b IS NULL);
 UPDATE public.shipments SET tracking_poll_until=now()-interval '1 second' WHERE order_id=o;
 SELECT value INTO b FROM public.claim_tracking_refresh(owner_b,20) value WHERE value->>'order_id'=o::text;
 INSERT INTO retry_checks VALUES('crashed worker lease can be recovered',b->>'tracking_poll_owner'=owner_b::text);
 UPDATE public.shipments SET tracking_poll_until=NULL,next_tracking_poll_at=now()+interval '5 minutes' WHERE order_id=o;
 SELECT value INTO b FROM public.claim_tracking_refresh(owner_a,20) value WHERE value->>'order_id'=o::text;
 INSERT INTO retry_checks VALUES('tracking waits until next poll',b IS NULL);
 UPDATE public.orders SET status='DISPUTED' WHERE id=o;
 UPDATE public.shipments SET next_tracking_poll_at=now() WHERE order_id=o;
 SELECT value INTO b FROM public.claim_tracking_refresh(owner_a,20) value WHERE value->>'order_id'=o::text;
 INSERT INTO retry_checks VALUES('dispute is not advanced by tracking',b IS NULL);
 INSERT INTO retry_checks VALUES('public roles cannot access attempts or tracking claims',NOT has_table_privilege('anon','public.checkout_attempts','SELECT') AND NOT has_table_privilege('authenticated','public.checkout_attempts','SELECT') AND NOT has_function_privilege('anon','public.reserve_checkout_attempt(text,text,text,text,text,jsonb)','EXECUTE') AND NOT has_function_privilege('authenticated','public.claim_tracking_refresh(uuid,integer)','EXECUTE'));
 IF EXISTS(SELECT 1 FROM retry_checks WHERE NOT passed) THEN RAISE EXCEPTION 'Retry/tracking regression'; END IF;
END $$;
SELECT jsonb_build_object('passed',bool_and(passed),'count',count(*),'checks',jsonb_agg(to_jsonb(retry_checks))) AS result FROM retry_checks;
ROLLBACK;
